begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,auth;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',id::uuid,'authenticated','authenticated',name||'@training.example.test','',now(),'{}','{}',now(),now()
from (values
('91111111-1111-4111-8111-111111111111','client-a'),('92222222-2222-4222-8222-222222222222','client-b'),
('93333333-3333-4333-8333-333333333333','coach-a'),('94444444-4444-4444-8444-444444444444','coach-b'),
('95555555-5555-4555-8555-555555555555','free'),('96666666-6666-4666-8666-666666666666','admin'))u(id,name);
update public.user_roles set role='coach' where user_id in ('93333333-3333-4333-8333-333333333333','94444444-4444-4444-8444-444444444444');
update public.user_roles set role='admin' where user_id='96666666-6666-4666-8666-666666666666';
insert into public.user_subscriptions(user_id,plan_id,status,provider)
select u.id::uuid,p.id,'active','internal' from (values('91111111-1111-4111-8111-111111111111','premium'),('92222222-2222-4222-8222-222222222222','premium'),('93333333-3333-4333-8333-333333333333','coach'),('94444444-4444-4444-8444-444444444444','coach'),('96666666-6666-4666-8666-666666666666','premium'))u(id,code) join public.plans p on p.code=u.code;
insert into public.coach_client_relationships(coach_user_id,client_user_id,status) values('93333333-3333-4333-8333-333333333333','91111111-1111-4111-8111-111111111111','active');
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select set_config('qa.template',public.training_mutate('save_template',jsonb_build_object('name','Status security','items',jsonb_build_array(jsonb_build_object('exercise_id',(select id from public.exercises where owner_user_id is null limit 1)))))->>'id',true);
select set_config('qa.assignment',public.training_mutate('assign',jsonb_build_object('workout_template_id',current_setting('qa.template'),'client_id','91111111-1111-4111-8111-111111111111'))->>'id',true);
reset role; select set_config('qa.before',(select to_jsonb(a)::text from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),true);
set local role authenticated; select set_config('request.jwt.claim.sub','92222222-2222-4222-8222-222222222222',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Unrelated client');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Unrelated client leaves whole row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','94444444-4444-4444-8444-444444444444',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Unrelated coach');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Unrelated coach leaves whole row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','96666666-6666-4666-8666-666666666666',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Admin has no ownership override');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Admin has no ownership override leaves whole row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','91111111-1111-4111-8111-111111111111',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','coach_user_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply coach_user_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','client_user_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply client_user_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','relationship_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply relationship_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','workout_template_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply workout_template_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','program_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply program_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','owner_user_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply owner_user_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','user_id','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply user_id');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','created_at','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply created_at');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','updated_at','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply updated_at');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped','completed_at','92222222-2222-4222-8222-222222222222'))$$,'42501',null,'Client cannot supply completed_at');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'All rejected ownership changes leave whole row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','91111111-1111-4111-8111-111111111111',true);
select throws_ok($$update public.workout_assignments set client_user_id='92222222-2222-4222-8222-222222222222' where id=current_setting('qa.assignment')::uuid$$,'42501',null,'Direct ownership UPDATE denied');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'22023',null,'Client invalid target archived');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','completed'))$$,'22023',null,'Client invalid target completed');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','in_progress'))$$,'22023',null,'Client invalid target in_progress');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status',null))$$,'22023',null,'Client invalid target null');
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','assigned'))$$,'22023',null,'Client invalid target assigned');
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'Assigned client can skip');
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','assigned'))$$,'Assigned client can restore');
reset role; update public.coach_client_relationships set status='paused' where coach_user_id='93333333-3333-4333-8333-333333333333';
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'42501',null,'paused coach blocked');
select throws_ok($$select private.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'42501',null,'paused coach blocked through private entry');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'paused attempts preserve entire row');
reset role; update public.coach_client_relationships set status='ended',ended_at=now() where coach_user_id='93333333-3333-4333-8333-333333333333';
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'42501',null,'ended coach blocked');
select throws_ok($$select private.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'42501',null,'ended coach blocked through private entry');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'ended attempts preserve entire row');
reset role; update public.coach_client_relationships set status='active',ended_at=null where coach_user_id='93333333-3333-4333-8333-333333333333'; update public.user_roles set role='user' where user_id='93333333-3333-4333-8333-333333333333';
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'42501',null,'Coach plan without coach role blocked');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Missing role attempt unchanged');
update public.user_roles set role='coach' where user_id='93333333-3333-4333-8333-333333333333'; update public.user_subscriptions set plan_id=(select id from public.plans where code='premium') where user_id='93333333-3333-4333-8333-333333333333';
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'42501',null,'Coach role without coach_access blocked');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Missing entitlement attempt unchanged');
update public.user_subscriptions set plan_id=(select id from public.plans where code='coach') where user_id='93333333-3333-4333-8333-333333333333';
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'22023',null,'Coach cannot perform client skip');
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','archived'))$$,'Active assigned coach can archive');
select is((select status from public.workout_assignments where id=current_setting('qa.assignment')::uuid),'archived','Authorized archive persisted');
set local role authenticated; select set_config('request.jwt.claim.sub','91111111-1111-4111-8111-111111111111',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','assigned'))$$,'22023',null,'Client cannot restore coach archived assignment');
select set_config('qa.self_template',public.training_mutate('save_template',jsonb_build_object('name','Self status security','items',jsonb_build_array(jsonb_build_object('exercise_id',(select id from public.exercises where owner_user_id is null limit 1)))))->>'id',true);
select set_config('qa.assignment',public.training_mutate('assign',jsonb_build_object('workout_template_id',current_setting('qa.self_template')))->>'id',true);
reset role; select set_config('qa.before',(select to_jsonb(a)::text from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),true);
set local role authenticated; select set_config('request.jwt.claim.sub','92222222-2222-4222-8222-222222222222',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Unrelated client NULL coach');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Unrelated client NULL coach row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','93333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Active coach does not own self assignment');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Active coach does not own self assignment row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','96666666-6666-4666-8666-666666666666',true);
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Admin cannot modify another self assignment');
reset role; select is((select to_jsonb(a) from public.workout_assignments a where id=current_setting('qa.assignment')::uuid),current_setting('qa.before')::jsonb,'Admin cannot modify another self assignment row unchanged');
set local role authenticated; select set_config('request.jwt.claim.sub','91111111-1111-4111-8111-111111111111',true);
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'Self assigned client skip allowed');
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','assigned'))$$,'Self assigned client restore allowed');
reset role; update public.workout_assignments set client_user_id='96666666-6666-4666-8666-666666666666' where id=current_setting('qa.assignment')::uuid;
set local role authenticated; select set_config('request.jwt.claim.sub','96666666-6666-4666-8666-666666666666',true);
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'Admin as assigned client may skip');
select lives_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','assigned'))$$,'Admin as assigned client may restore');
reset role;
delete from public.user_subscriptions where user_id='96666666-6666-4666-8666-666666666666';
set local role authenticated;
select throws_ok($$select public.training_mutate('assignment_status',jsonb_build_object('id',current_setting('qa.assignment'),'status','skipped'))$$,'42501',null,'Admin still requires workout entitlement');
reset role;
select ok((select prosecdef from pg_proc where oid='private.training_mutate(text,jsonb)'::regprocedure),'Private trusted path is definer');
select ok(not (select prosecdef from pg_proc where oid='public.training_mutate(text,jsonb)'::regprocedure),'Public wrapper is invoker');
select ok(not has_function_privilege('anon','public.training_mutate(text,jsonb)','execute'),'Anonymous cannot execute public command');
select ok(not has_function_privilege('anon','private.training_mutate(text,jsonb)','execute'),'Anonymous cannot execute private command');
select ok(not has_table_privilege('authenticated','public.workout_assignments','update'),'Authenticated has no direct assignment update grant');
select * from finish(); rollback;
